import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    codes = torch.tensor([[0.8, 0.2], [0.2, 0.8]])
    return {"inputs": synth.Tensor(inputs), "codes": synth.Tensor(codes)}
dataset = synth.Spec("swav-two-view", generator=samples, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class TwoViewPredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=4)
    def forward(self, inputs):
        return {"scores": self.network(inputs).reshape(-1, 2, 2)}
trainer = Trainer(TwoViewPredictor(), train, recipe="structured-objective", recipe_config={"loss": "swav-loss", "loss_kwargs": {"temperature": 0.1}, "bindings": {"logits_or_prediction": {"output": "scores"}, "targets": {"batch": "codes"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
